const MISSING = {"status":"not_found","reason":"not in the Done scene"};

/** The id a per-input route is keyed by in KEYED. */
const inputIdOf = (route, input) => {
  const value = input ?? {};
  switch (route) {
    case 'goals/read': return value.goalId;
    case 'goals/display': case 'tasks/query': case 'architecture/change-scope': return value.goalRef?.goalId;
    case 'graph/detail': return `${value.node?.ref?.taskId}:${value.section}`;
    case 'verification/round': return value.roundRef !== undefined ? `round:${value.roundRef.roundId}`
      : value.taskRef !== undefined ? `task:${value.taskRef.taskId}` : `run:${value.subjectRunRef?.runId}`;
    case 'executions/read': return value.runId;
    case 'executions/brief': return value.runRef?.runId;
    case 'materials/open': return value.ref?.digest;
    default: return undefined;
  }
};

/** `files/uncommitted` answers the paths the input names, `activity/runs` the Runs it names. */
const named = (route, input) => {
  const answer = ROUTES[route];
  if (route === 'files/uncommitted' && Array.isArray(input?.paths)) {
    const byPath = new Map(answer.value.files.map((file) => [file.path, file]));
    return { ...answer, value: { ...answer.value, files: input.paths.map((path) => byPath.get(path) ?? { path, state: 'unknown' }) } };
  }
  if (route === 'activity/runs' && Array.isArray(input?.runRefs)) {
    const ids = new Set(input.runRefs.map((ref) => ref?.runId));
    return { ...answer, value: answer.value.filter((item) => ids.has(item.runRef.runId)) };
  }
  return answer;
};

export const scene = {
  now: "2026-10-23T09:00:01.000Z",
  routes: ROUTES,
  reply(route, input) {
    if (route in KEYED) return KEYED[route][inputIdOf(route, input)] ?? MISSING;
    return named(route, input);
  },
};
